changeSet.sql:
CREATE TABLE oauth2_authorization_consent (
    registered_client_id varchar(100) NOT NULL,
    principal_name varchar(200) NOT NULL,
    authorities varchar(1000) NOT NULL,
    PRIMARY KEY (registered_client_id, principal_name)
);

CREATE INDEX ix_oauth2_authorization_principal_name ON oauth2_authorization (principal_name);
CREATE INDEX ix_oauth2_authorization_state ON oauth2_authorization (state) WHERE state IS NOT NULL;
CREATE INDEX ix_oauth2_authorization_auth_code ON oauth2_authorization (authorization_code_value)
    WHERE authorization_code_value IS NOT NULL;
CREATE INDEX ix_oauth2_authorization_access_token ON oauth2_authorization (access_token_value)
    WHERE access_token_value IS NOT NULL;
CREATE INDEX ix_oauth2_authorization_refresh_token ON oauth2_authorization (refresh_token_value)
    WHERE refresh_token_value IS NOT NULL;

rollback.sql:
DROP INDEX ix_oauth2_authorization_principal_name;
DROP INDEX ix_oauth2_authorization_state;
DROP INDEX ix_oauth2_authorization_auth_code;
DROP INDEX ix_oauth2_authorization_access_token;
DROP INDEX ix_oauth2_authorization_refresh_token;
